insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('2d291214-7d02-4747-be5e-9d0df3a971d3', '51ed1e63-45b7-44cf-86f9-f57985e3afe2', $$cashewnoten uit Tanzania worden geveild; alle noten van dezelfde soort en kwaliteit$$,
   $$economie-havo-2024-ii-cashewnoten-context1.png$$,
   $$Cashewnoten zijn een belangrijk exportproduct voor Tanzania en een belangrijke bron van inkomsten voor de vele cashewnotenboeren in dat land. De cashewnotenboeren bieden hun oogst aan op een veiling. De veilingklok laat een hoge startprijs zien. Daarna zakt de prijs per kilogram, totdat een koper akkoord is en de cashewnoten koopt voor de aangegeven prijs. Alle cashewnoten zijn van dezelfde soort en kwaliteit.$$, 'inline'),
  ('2d4d4e85-a55f-406c-801b-317eeb1ed023', '51ed1e63-45b7-44cf-86f9-f57985e3afe2', $$marktprijs 1.550 shilling; minimumprijs 3.300 shilling; overschot opgekocht door de overheid$$,
   $$economie-havo-2024-ii-cashewnoten-context2.png$$,
   $$Op de veiling is een gemiddelde marktprijs van 1.550 Tanzaniaanse shilling per kilogram tot stand gekomen. Volgens de boeren is deze marktprijs te laag om de productiekosten te dekken. Om de boeren te behoeden voor faillissement, kondigt de president van Tanzania een minimumprijs van 3.300 Tanzaniaanse shilling per kilogram aan. Het overschot dat als gevolg van de minimumprijs ontstaat, zal worden opgekocht door de overheid. De nieuwe marktsituatie is geschetst in bron 1.$$, 'inline'),
  ('701f6064-97fb-4fb7-a4a6-12ad6ba3cf26', '51ed1e63-45b7-44cf-86f9-f57985e3afe2', $$definitie prijselasticiteit van het aanbod (Ea)$$,
   $$economie-havo-2024-ii-cashewnoten-context3.png$$,
   $$De prijselasticiteit van het aanbod (Ea) is gedefinieerd als:$$, 'inline'),
  ('0f70b211-05dd-4d8b-bc0d-77a60fb41170', '51ed1e63-45b7-44cf-86f9-f57985e3afe2', $$formule Ea$$,
   $$economie-havo-2024-ii-cashewnoten-context4.png$$,
   $$Ea = % verandering aangeboden hoeveelheid / % verandering prijs$$, 'inline'),
  ('a35287ab-40c1-4870-8667-97ad0dd00b05', '51ed1e63-45b7-44cf-86f9-f57985e3afe2', $$een econoom: kopers en burgers ondervinden financieel nadeel van de ingreep$$,
   $$economie-havo-2024-ii-cashewnoten-context5.png$$,
   $$Bij het besluit om in te grijpen in de markt, heeft de overheid een afweging gemaakt tussen de belangen van verschillende groepen in de samenleving. Een econoom stelt dat twee groepen financieel nadeel ondervinden van de ingreep: de kopers van de cashewnoten en de burgers van het land.$$, 'inline'),
  ('19f5d9db-f866-48f3-ae51-025cd636f8b4', '51ed1e63-45b7-44cf-86f9-f57985e3afe2', $$een econoom over investeringen in arbeidsproductiviteit-verhogende technologieën$$,
   $$economie-havo-2024-ii-cashewnoten-context6.png$$,
   $$Een econoom stelt: “Om te kunnen concurreren met andere landen waar cashewnoten worden geproduceerd, zijn economische structuurontwikkelingen nodig. Bijvoorbeeld investeringen in nieuwe technologieën die leiden tot een toename van de arbeidsproductiviteit. Op de korte-termijn kunnen deze investeringen leiden tot een vermindering van de werkgelegenheid op de cashewnotenmarkt, maar op de lange-termijn zijn ze noodzakelijk voor het herstel ervan.” Het korte-termijn effect is in de figuur weergegeven door pijl 1. Het lange-termijn effect is in de figuur weergegeven door pijl 2 en pijl 3.$$, 'inline'),
  ('3d54541d-e9d5-427a-83b9-3ab85e412c0b', '51ed1e63-45b7-44cf-86f9-f57985e3afe2', $$figuur: pijlen 1, 2 en 3 tussen investeringen, werkgelegenheid en internationale concurrentiepositie$$,
   $$economie-havo-2024-ii-cashewnoten-context7.png$$,
   $$figuur:
investeringen in arbeidsproductiviteit verhogende technologieën → (1, −) → werkgelegenheid
investeringen in arbeidsproductiviteit verhogende technologieën → (2, +) → internationale concurrentiepositie → (3, +) → werkgelegenheid
Toelichting: een “–“ betekent een negatief verband, een “+” betekent een positief verband.$$, 'inline'),
  ('8e306eaa-c74e-4a17-af06-b93b82c6c5f2', '51ed1e63-45b7-44cf-86f9-f57985e3afe2', $$bron 1: vereenvoudigde weergave cashewnotenmarkt van Tanzania$$,
   $$economie-havo-2024-ii-cashewnoten-context8.png$$,
   $$Bron 1 Vereenvoudigde weergave cashewnotenmarkt van Tanzania
(grafiek: prijs in shilling per kilogram tegen hoeveelheid in kilogram; dalende vraaglijn Qv van K via I en G naar D; verticale aanbodlijn Qa bij C door J en G; Pmin 3.300 bij H met horizontale lijn door I en J; Pe 1.550 bij E met horizontale lijn door F en G; B onder I en F op de hoeveelheid-as; A = oorsprong)
Pmin minimumprijs per kilogram in Tanzaniaanse shilling
Pe evenwichtsprijs per kilogram in Tanzaniaanse shilling
Qv gevraagde hoeveelheid cashewnoten in kilogram
Qa aangeboden hoeveelheid cashewnoten in kilogram$$, 'inline'),
  ('6828bed6-59b2-461a-9a68-29991542d357', '9c250384-79c4-4781-89d4-96903dd2b7d5', $$uit een krant, januari 2024$$,
   $$economie-havo-2024-ii-kiezen-voor-een-tandarts-context1.png$$,
   $$Uit een krant, januari 2024:$$, 'inline'),
  ('b16e0f40-2bda-40e0-8db4-477162b47133', '9c250384-79c4-4781-89d4-96903dd2b7d5', $$meer marktwerking in de tandzorg: tandartsen bepalen zelf hun tarieven$$,
   $$economie-havo-2024-ii-kiezen-voor-een-tandarts-context2.png$$,
   $$De overheid van een land wil meer marktwerking in de tandzorg. Vandaar dat er vanaf 1 januari 2024 nieuw beleid van kracht is, waarbij de aanbieders van tandzorg (tandartsen) zelf de tarieven voor hun diensten mogen bepalen. Tandartsen zijn voorstander van dit nieuwe beleid, omdat ze zich dan beter kunnen onderscheiden op kwaliteit. Voorheen werden de tarieven vastgesteld door de overheid. De overheid verwacht dat de marktwerking ertoe zal leiden dat vragers van tandzorg (patiënten) vaker gaan veranderen van tandarts. Er zijn in het land ongeveer 9.000 tandartsen werkzaam en dat is volgens de overheid voldoende om aan de vraag naar tandzorg te voldoen.$$, 'inline'),
  ('a5ac919b-4502-43c9-be0e-5fb41b8e3361', '9c250384-79c4-4781-89d4-96903dd2b7d5', $$de markt voor tandzorg vertoont kenmerken van monopolistische concurrentie$$,
   $$economie-havo-2024-ii-kiezen-voor-een-tandarts-context3.png$$,
   $$De markt voor tandzorg in dit land vertoont sinds 1 januari 2024 kenmerken van monopolistische concurrentie.$$, 'inline'),
  ('5c30ac0e-a2bb-468a-aa30-90cc37b161eb', '9c250384-79c4-4781-89d4-96903dd2b7d5', $$drie uitspraken van gezondheidseconomen over marktwerking in de tandzorg$$,
   $$economie-havo-2024-ii-kiezen-voor-een-tandarts-context4.png$$,
   $$Enkele gezondheidseconomen reageren op het nieuwe beleid van de overheid en doen de volgende uitspraken:
1 “Marktwerking zal leiden tot lagere prijzen van tandzorg.”
2 “Als veel patiënten tegen de kosten van tandzorg zijn verzekerd, zal marktwerking niet leiden tot lagere prijzen.”
3 “De overheid zal erop moeten toezien dat tandartsen geen prijsafspraken met elkaar maken.”$$, 'inline'),
  ('fdb96656-8386-4d6c-83d3-06ebf6c049be', '9c250384-79c4-4781-89d4-96903dd2b7d5', $$Denzel Martina overweegt over te stappen of een tandzorgverzekering af te sluiten$$,
   $$economie-havo-2024-ii-kiezen-voor-een-tandarts-context5.png$$,
   $$Denzel Martina is niet verzekerd tegen de kosten van tandzorg. Denzel bezoekt ieder half jaar het Mondmedisch Centrum in zijn woonplaats voor een gebitscontrole. Uit landelijke statistieken blijkt dat patiënten die één keer per halfjaar een gebitscontrole laten uitvoeren, gemiddeld een keer per vier jaar een vervolgbehandeling nodig hebben. Per 1 januari 2024 verhoogt het Mondmedisch Centrum de tarieven, en daarom overweegt Denzel het volgende:
− Hij stapt over naar tandartspraktijk De Concurrent.
− Hij sluit een tandzorgverzekering af.$$, 'inline'),
  ('51a6cbdb-91d2-40d1-953c-86283f8c3794', '9c250384-79c4-4781-89d4-96903dd2b7d5', $$Denzel is risiconeutraal en verwacht geen verandering in zijn zorgconsumptie$$,
   $$economie-havo-2024-ii-kiezen-voor-een-tandarts-context6.png$$,
   $$Denzel heeft een risiconeutrale houding ten opzichte van de kosten en verwacht geen verandering in zijn zorgconsumptie.$$, 'inline'),
  ('f79efbbf-6f62-4044-87ce-68ffb60eafb6', '9c250384-79c4-4781-89d4-96903dd2b7d5', $$Denzel maakt een overzicht$$,
   $$economie-havo-2024-ii-kiezen-voor-een-tandarts-context7.png$$,
   $$Denzel Martina maakt het volgende overzicht:$$, 'inline'),
  ('460c5206-12e6-41bd-8bd5-f160e44157f9', '9c250384-79c4-4781-89d4-96903dd2b7d5', $$tabel: tarieven gebitscontrole en vervolgbehandeling, eigen risico en premie$$,
   $$economie-havo-2024-ii-kiezen-voor-een-tandarts-context8.png$$,
   $$| gebitscontrole | vervolgbehandeling
oud tarief Mondmedisch Centrum | € 24 per halfjaar | € 50 per behandeling
nieuw tarief Mondmedisch Centrum | € 28 per halfjaar | € 60 per behandeling
tarief De Concurrent | € 26 per halfjaar | € 70 per behandeling
eigen risico tandzorgverzekering | geen eigen risico | € 5 eigen risico per behandeling
premie tandzorgverzekering | € 69 per jaar$$, 'inline'),
  ('048a9b4e-fc1c-4605-a4fe-c4b4c363fafb', '59718928-da51-4bb8-bb38-2037d706519d', $$scholingskosten zijn aftrekbaar voor de inkomstenbelasting$$,
   $$economie-havo-2024-ii-studiekosten-context1.png$$,
   $$De overheid van een land stimuleert de scholing van volwassenen. Daarom kent het land een regeling waarbij scholingskosten aftrekbaar zijn voor de inkomstenbelasting. Een voorwaarde voor belastingaftrek is dat de studie gericht moet zijn op een beroep en niet op een hobby.$$, 'inline'),
  ('9fc1ceab-a41f-457e-ad36-8b7b79169a04', '59718928-da51-4bb8-bb38-2037d706519d', $$bij controle van de voorwaarden kan de overheid te maken krijgen met asymmetrische informatie$$,
   $$economie-havo-2024-ii-studiekosten-context2.png$$,
   $$Niet alle opleidingstrajecten leiden tot een baan met voldoende inkomen. Bij het controleren van de voorwaarden voor scholingskostenaftrek kan de overheid te maken krijgen met asymmetrische informatie.$$, 'inline'),
  ('2c48d8be-d0ec-4a18-93bd-ea6042c07dcc', '59718928-da51-4bb8-bb38-2037d706519d', $$econoom: hoogste inkomens maken meer gebruik van de regeling; progressief stelsel met drie schijven$$,
   $$economie-havo-2024-ii-studiekosten-context3.png$$,
   $$Een econoom stelt dat mensen in de hoogste inkomenscategorie meer gebruikmaken van de regeling dan mensen in de lagere inkomenscategorieën. Dit wordt versterkt doordat het land een progressief belastingstelsel kent met drie schijven, zie bron 1.$$, 'inline'),
  ('a1b99ad2-a832-4a61-b0c4-4e5455606c83', '59718928-da51-4bb8-bb38-2037d706519d', $$Denise overweegt een universitaire master orthopedagogiek$$,
   $$economie-havo-2024-ii-studiekosten-context4.png$$,
   $$Denise heeft haar hbo-studie pedagogiek met succes afgerond en is inmiddels een aantal jaren werkzaam als leerlingbegeleider. Zij overweegt om volgend jaar in de avonduren te gaan studeren voor een universitaire master orthopedagogiek. Ze wil graag weten wat deze studie haar volgend jaar zou kosten.$$, 'inline'),
  ('8b70dddd-9472-4913-84ae-9e28a114d6d3', '59718928-da51-4bb8-bb38-2037d706519d', $$kosten master: collegegeld € 2.300, studiematerialen € 400$$,
   $$economie-havo-2024-ii-studiekosten-context5.png$$,
   $$De kosten voor de eenjarige master orthopedagogiek zijn:
− collegegeld: € 2.300
− studiematerialen: € 400$$, 'inline'),
  ('45bf5f27-9da7-44f1-bc62-1698d85ec8bb', '59718928-da51-4bb8-bb38-2037d706519d', $$drempel € 300; bruto-inkomen € 36.000; geen andere aftrekposten$$,
   $$economie-havo-2024-ii-studiekosten-context6.png$$,
   $$Denise mag de kosten boven de drempel van € 300 aftrekken. Ze heeft volgend jaar een bruto-inkomen van € 36.000. Zij heeft geen andere aftrekposten.$$, 'inline'),
  ('adac7502-03bc-42e7-b721-ac1e3554b270', '59718928-da51-4bb8-bb38-2037d706519d', $$bron 1: belastingschijven en de bijbehorende belastingtarieven$$,
   $$economie-havo-2024-ii-studiekosten-context7.png$$,
   $$Bron 1 Belastingschijven en de bijbehorende belastingtarieven
belastbaar inkomen € 0 tot € 37.149: 19,03%
belastbaar inkomen € 37.149 tot € 73.031: 36,93%
belastbaar inkomen vanaf € 73.031: 49,50%$$, 'inline'),
  ('c7e1db97-f57a-41e9-990f-3434a5d01119', '4a309abd-d902-4380-af46-68239527a061', $$uit een krant$$,
   $$economie-havo-2024-ii-rente-omlaag-maar-dan-context1.png$$,
   $$Uit een krant:$$, 'inline'),
  ('5d2813bd-462c-45e1-b5d4-316ed463dd1d', '4a309abd-d902-4380-af46-68239527a061', $$de ECB verlaagt haar rentetarief naar 0,05% om deflatie te voorkomen$$,
   $$economie-havo-2024-ii-rente-omlaag-maar-dan-context2.png$$,
   $$De Europese Centrale Bank (ECB) heeft haar belangrijkste rentetarief verlaagd naar 0,05% per jaar. Dit rentebesluit is genomen om te voorkomen dat er deflatie ontstaat, als gevolg van de laagconjunctuur waarin de Europese economie zich bevindt. Verwacht wordt dat de renteverlaging zal doorwerken in andere rentetarieven. Dat kan tot gevolg hebben dat:
− spaarders zullen overstappen naar aandelen;
− particuliere bestedingen (consumptie en investeringen) toenemen;
− meer huurders een eigen woning gaan aanschaffen.$$, 'inline'),
  ('c3e2374c-b56e-4621-9b1b-4c4a80fb62f0', '4a309abd-d902-4380-af46-68239527a061', $$een econoom reageert met twee beweringen$$,
   $$economie-havo-2024-ii-rente-omlaag-maar-dan-context3.png$$,
   $$Een econoom reageert op het krantenbericht met twee beweringen.$$, 'inline'),
  ('590c4031-d1d7-4d24-b01d-7895de89e768', '4a309abd-d902-4380-af46-68239527a061', $$bewering 1: bedrijfsinvesteringen nemen in een laagconjunctuur nauwelijks toe$$,
   $$economie-havo-2024-ii-rente-omlaag-maar-dan-context4.png$$,
   $$Bewering 1: “Door de renteverlaging zullen in een laagconjunctuur de bedrijfsinvesteringen nauwelijks toenemen.”$$, 'inline'),
  ('aa65d0d9-3733-4cd9-aea2-aee89d8bb608', '4a309abd-d902-4380-af46-68239527a061', $$bewering 2: de afweging huren of kopen hangt van meer af dan de rente$$,
   $$economie-havo-2024-ii-rente-omlaag-maar-dan-context5.png$$,
   $$Bewering 2: “De afweging van huurders om nu al dan niet over te gaan tot koop van een eigen woning, is gebaseerd op veel meer factoren dan alleen de hoogte van het rentetarief. Ik heb een voorbeeld uitgewerkt (bron 1).”$$, 'inline'),
  ('9b2ce50e-0f86-49a6-9fe0-fbd85cb94a65', '4a309abd-d902-4380-af46-68239527a061', $$bron 1: uitgewerkt voorbeeld van de afweging kopen of huren$$,
   $$economie-havo-2024-ii-rente-omlaag-maar-dan-context6.png$$,
   $$Bron 1 Uitgewerkt voorbeeld van de afweging: kopen of huren
Een huurder heeft de volgende verwachtingen voor de komende jaren:
− in het eerste jaar bedraagt de huur € 7.200;
− de huur stijgt jaarlijks op 1 januari met 4%;
− een vergelijkbare koopwoning kost € 240.000;
− de rente van een hypothecaire lening waarop niet wordt afgelost blijft 2% per jaar;
− de koopwoning wordt volledig gefinancierd met een hypothecaire lening;
− de extra kosten van een koopwoning ten opzichte van een huurwoning (onderhoud, etc.) worden de komende jaren geschat op € 250 per maand.$$, 'inline'),
  ('091568d4-23c6-423a-bc1f-39f96aa92933', '1ae49e80-de76-4f6d-8365-643723b49835', $$het CPB analyseert de houdbaarheid van de overheidsfinanciën (houdbaarheidssaldo)$$,
   $$economie-havo-2024-ii-zorgen-om-morgen-context1.png$$,
   $$Door een stijgende levensverwachting en minder geboorten verandert de samenstelling van de Nederlandse bevolking. Het Centraal Planbureau (CPB) analyseert de gevolgen hiervan voor de overheidsfinanciën en voor de solidariteit tussen generaties. Hiervoor kijkt het CPB naar het houdbaarheidssaldo. Het houdbaarheidssaldo geeft aan of het huidige niveau van de overheidsvoorzieningen op lange termijn betaalbaar en houdbaar is, zonder dat de overheidsschuld oploopt of de belastinginkomsten moeten worden verhoogd.$$, 'inline'),
  ('4371940d-3083-4077-8d52-0dcfbf35f809', '1ae49e80-de76-4f6d-8365-643723b49835', $$voorbeelden van gelijkblijvende overheidsvoorzieningen$$,
   $$economie-havo-2024-ii-zorgen-om-morgen-context2.png$$,
   $$Voorbeelden van gelijkblijvende overheidsvoorzieningen zijn:
− dat er in de toekomst voor elke leerling evenveel leraren zijn als nu,
− dat er voor elke oudere evenveel handen aan het bed zijn als nu,
− dat uitkeringen welvaartsvast zijn.$$, 'inline'),
  ('49a06bf2-614d-4824-8bf7-4aad3a5048fc', '1ae49e80-de76-4f6d-8365-643723b49835', $$houdbaarheidstekort: voorzieningen in de toekomst slechter betaalbaar$$,
   $$economie-havo-2024-ii-zorgen-om-morgen-context3.png$$,
   $$Als er een houdbaarheidstekort is, dan betekent dit dat de voorzieningen in de toekomst slechter betaalbaar zijn.$$, 'inline'),
  ('2938f3a8-274e-4024-b16f-5184bd0a01f4', '1ae49e80-de76-4f6d-8365-643723b49835', $$het aantal 67-plussers als percentage van de 20- tot 66-jarigen stijgt sterk (zie bron 1)$$,
   $$economie-havo-2024-ii-zorgen-om-morgen-context4.png$$,
   $$Het CPB constateert dat de leeftijdsopbouw van de bevolking verandert en dat het aantal 67-plussers als percentage van het aantal 20- tot 66-jarigen in de periode tot 2040 sterk zal stijgen (zie bron 1).$$, 'inline'),
  ('4d1587c5-1228-44ee-9110-7ef260b7ac8f', '1ae49e80-de76-4f6d-8365-643723b49835', $$het CPB verwacht dat het arbeidsaanbod van 20- tot 66-jarigen toeneemt$$,
   $$economie-havo-2024-ii-zorgen-om-morgen-context5.png$$,
   $$Aan de andere kant verwacht het CPB dat het aanbod van arbeid binnen de groep van 20- tot 66-jarigen zal toenemen, doordat een groter deel van die groep besluit te gaan werken.$$, 'inline'),
  ('8c430bd7-a1f0-437d-b72b-5e93e1de8c51', '1ae49e80-de76-4f6d-8365-643723b49835', $$beleidsopties: belastingtarieven 1 procentpunt omhoog of uitkeringen inclusief AOW omlaag$$,
   $$economie-havo-2024-ii-zorgen-om-morgen-context6.png$$,
   $$De recente verhoging van de pensioenleeftijd lost het houdbaarheidstekort gedeeltelijk op. Om de betaalbaarheid van overheidsvoorzieningen verder te verbeteren, stelt een econoom een aantal beleidsopties voor aan de Nederlandse regering:
1 Verhoog het tarief van alle belastingschijven in het progressieve belastingstelsel met 1 procentpunt.
2 Verlaag de uitkeringen, inclusief de AOW.$$, 'inline'),
  ('45fb9b9b-6d1b-45f4-a86d-916725360cff', '1ae49e80-de76-4f6d-8365-643723b49835', $$een van de beleidsopties kan leiden tot een daling van het arbeidsaanbod$$,
   $$economie-havo-2024-ii-zorgen-om-morgen-context7.png$$,
   $$Een van de twee beleidsopties kan leiden tot een daling van het arbeidsaanbod.$$, 'inline'),
  ('75d21dec-0b13-4bc6-a0e4-c93b89f7ec80', '1ae49e80-de76-4f6d-8365-643723b49835', $$een van de beleidsopties leidt tot denivellering$$,
   $$economie-havo-2024-ii-zorgen-om-morgen-context8.png$$,
   $$Een van de twee beleidsopties leidt tot denivellering.$$, 'inline'),
  ('9ae9170b-1700-4776-ba14-041448cfc78c', '1ae49e80-de76-4f6d-8365-643723b49835', $$bron 1: grijze druk$$,
   $$economie-havo-2024-ii-zorgen-om-morgen-context9.png$$,
   $$Bron 1 Grijze druk
(lijngrafiek grijze druk in procenten, 1950-2060: stijgt geleidelijk tot ongeveer 2010, daarna sterk tot ongeveer 50% rond 2040 en blijft daarna ongeveer gelijk)
Grijze druk is gedefinieerd als het aantal 67-plussers als percentage van het aantal 20- tot 66-jarigen.$$, 'inline'),
  ('5ce43a98-6046-4777-a1c2-d026b619de96', '23fe6f23-4068-4126-9f86-47cc54ca7a3c', $$gemeente gunt de bouw aan twee aannemers; Bouwrijk stelt een verdeling voor, Schot in de Zaak stemt in of weigert$$,
   $$economie-havo-2024-ii-aanbesteding-context1.png$$,
   $$De gemeente wil een nieuw gemeentehuis laten bouwen. Gezien de complexiteit van de bouw, wil de gemeente de opdracht aan twee aannemers (Bouwrijk en Schot in de Zaak) gunnen. De gemeente zal de totale aanneemsom betalen aan aannemer Bouwrijk. Vooraf stelt de gemeente de volgende voorwaarde: Bouwrijk stelt een verdeling van het bedrag voor. Vervolgens moet Schot in de Zaak besluiten om in te stemmen of te weigeren. Er is geen mogelijkheid voor onderhandelen, omdat de gemeente snel een antwoord verwacht. Bij weigering gaat de opdracht naar twee andere aannemers. Aannemer Bouwrijk gaat voortvarend te werk en doet Schot in de Zaak een voorstel voor een verdeling van de totale aanneemsom.$$, 'inline'),
  ('f5bde2f6-4a6b-43ce-8690-2937592cbbfe', '23fe6f23-4068-4126-9f86-47cc54ca7a3c', $$de totale aanneemsom en de startkosten voor beide bedrijven$$,
   $$economie-havo-2024-ii-aanbesteding-context2.png$$,
   $$De totale aanneemsom en de startkosten voor beide bedrijven zijn als volgt:$$, 'inline'),
  ('8f50377f-64e8-442d-a0dc-c55414fd0551', '23fe6f23-4068-4126-9f86-47cc54ca7a3c', $$tabel: totale aanneemsom € 485.000; startkosten Bouwrijk € 12.500; startkosten Schot in de Zaak € 25.000$$,
   $$economie-havo-2024-ii-aanbesteding-context3.png$$,
   $$totale aanneemsom | startkosten Bouwrijk | startkosten Schot in de Zaak
€ 485.000 | € 12.500 | € 25.000$$, 'inline'),
  ('b4087479-6fcf-4ae4-8172-0ea20de5008e', '23fe6f23-4068-4126-9f86-47cc54ca7a3c', $$twee situaties: a nooit meer samenwerken, b vaker samenwerken$$,
   $$economie-havo-2024-ii-aanbesteding-context4.png$$,
   $$Er zijn voor de toekomst twee situaties mogelijk: a De twee aannemers zullen in de toekomst nooit meer met elkaar samenwerken. b De twee aannemers zullen in de toekomst vaker met elkaar samenwerken.$$, 'inline'),
  ('31a8e3af-4803-4af5-91e5-fcaf8fb4e30b', '23fe6f23-4068-4126-9f86-47cc54ca7a3c', $$de aannemers houden rekening met een sociale norm$$,
   $$economie-havo-2024-ii-aanbesteding-context5.png$$,
   $$Stel dat de twee aannemers bij hun strategie rekening houden met een sociale norm.$$, 'inline'),
  ('f0975aac-446e-4524-aca8-43253a9a6aae', '23fe6f23-4068-4126-9f86-47cc54ca7a3c', $$aansprakelijkheidsverzekering met keuze tussen hoog of laag eigen risico$$,
   $$economie-havo-2024-ii-aanbesteding-context6.png$$,
   $$De aannemers hebben in hun startkosten de kosten van een aansprakelijkheidsverzekering meegenomen. De verzekeraar biedt de keuze tussen een hoog of een laag eigen risico.$$, 'inline');

